import{H as e,U as t,s as n,tt as r}from"./chunks/framework.Dz4btzT0.js";var i=JSON.parse(`{"title":"接收稿件","description":"","frontmatter":{"layout":"doc","title":"接收稿件"},"headers":[],"relativePath":"information/submit-arts.md","filePath":"information/submit-arts.md"}`),a={name:`information/submit-arts.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="接收稿件" tabindex="-1">接收稿件 <a class="header-anchor" href="#接收稿件" aria-label="Permalink to “接收稿件”">​</a></h1><blockquote><p>该文档同时适用于主动投稿和我方约稿。</p></blockquote><h2 id="权利归属" tabindex="-1">权利归属 <a class="header-anchor" href="#权利归属" aria-label="Permalink to “权利归属”">​</a></h2><p>如无另行说明，我方将会在保留画师署名的情况下，要求买断永久版权，因此需要提供原始项目文件和成品文件。</p><p>在默认情况下，我方将会对包括原始项目在内的文件以 <a href="https://creativecommons.org/licenses/by-sa/4.0/legalcode.zh-hans" target="_blank" rel="noreferrer">CC BY-SA 4.0 International</a> 协议对外发布，若对公开原始项目文件有担忧，与我方交涉后也可仅公开成品文件，但请注意成品文件将依然按该协议对外发布。</p><h2 id="项目文件" tabindex="-1">项目文件 <a class="header-anchor" href="#项目文件" aria-label="Permalink to “项目文件”">​</a></h2><p>请将以下文件以压缩包的形式发送给我们：</p><ul><li>原始项目文件</li><li>成品文件</li></ul><h3 id="支持直接提交的项目文件" tabindex="-1">支持直接提交的项目文件 <a class="header-anchor" href="#支持直接提交的项目文件" aria-label="Permalink to “支持直接提交的项目文件”">​</a></h3><p>考虑到我们的设备对不同格式的支持有限，因此我们支持直接提交以下原始项目文件：</p><ul><li>Krita 项目文件 (<code>.kra</code>)</li><li>Adobe Photoshop PSD 项目文件 (<code>.psd</code>)</li><li>Inkscape SVG 文件 (<code>.svg</code>)</li><li>带有多图层的 TIFF 文件 (<code>.tif</code> / <code>.tiff</code>)</li><li>GIMP 项目文件 (<code>.xcf</code>)</li><li>OpenToonz 项目 (<code>.tnz</code>)</li></ul><h3 id="支持提交的成品文件" tabindex="-1">支持提交的成品文件 <a class="header-anchor" href="#支持提交的成品文件" aria-label="Permalink to “支持提交的成品文件”">​</a></h3><p>我们支持提交以下成品文件：</p><ul><li>便携式网络图形 (<code>.png</code>)</li><li>WebP 图形 (<code>.webp</code>)</li><li>AV1 图像文件格式 (<code>.avif</code>)</li></ul><h3 id="无法直接接收的项目文件" tabindex="-1">无法直接接收的项目文件 <a class="header-anchor" href="#无法直接接收的项目文件" aria-label="Permalink to “无法直接接收的项目文件”">​</a></h3><p>我们主要使用 Linux 发行版，甚至有时会使用完全不支持 Windows / macOS 的设备，恕我们无法<strong>直接接收</strong>以下项目文件：</p><ul><li>CLIP STUDIO PAINT / 优动漫 PAINT 项目文件 (<code>.clip</code> / <code>.lip</code>)</li><li>PaintTool SAI 项目文件 (<code>.sai</code> / <code>.sai2</code>)</li><li>openCanvas 项目文件 (<code>.oci</code> / <code>.oc6</code>)</li><li>FireAlpaca / MediBang Paint 项目文件 (<code>.mdp</code>)</li><li>Corel Painter RIFF 文件 (<code>.rif</code> / <code>.riff</code>)</li><li>Procreate 项目文件 (<code>.procreate</code>)</li><li>画世界项目文件 (<code>.hsj</code>)</li><li>天生会画项目文件 (<code>.gopaint</code>)</li></ul><p>若使用以上软件创作，请保留原始项目文件，且根据指引将其转换或导出为 PSD 或 TIFF 文件后，一起发送给我们。若在该过程中遇到问题，也可联系我们寻求帮助。</p>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};